{
  "types": [
    {
      "type": "AlarmBannerObject",
      "description": "Displays a live alarm list from the ENVISION alarm system with configurable columns, colors, and acknowledgement support."
    },
    {
      "type": "AlarmViewerObject",
      "description": "Embeds the full Alarm Viewer page on a runtime page. It shows the whole plant: apart from geometry, border, visibility and access control it has no settings, so scope an area view with an AlarmBannerObject (data-assets) instead. The framed page keeps enforcing its own user-group rights. Sizing: give the frame at least 80% of the screen width (about 1536 px on a 1920 px wide screen) so the framed page\u0027s toolbar, filters and table columns stay usable."
    },
    {
      "type": "AuditTrailViewerObject",
      "description": "Embeds the full Audit Trail page on a runtime page, for showing the configuration and operator action history to an operator. Apart from geometry, border, visibility and access control it has no settings of its own, and the framed page keeps enforcing its own user-group rights. Sizing: give the frame at least 80% of the screen width (about 1536 px on a 1920 px wide screen) so the framed page\u0027s toolbar, filters and table columns stay usable."
    },
    {
      "type": "BarGraphObject",
      "description": "A bar or horizontal bar chart for comparing categorical data from a JSON variable source."
    },
    {
      "type": "ButtonObject",
      "description": "A clickable button that can display on/off state text and trigger actions. Supports variable binding for state-driven color changes. When setting a text and/or font-size, be aware of the width/height and padding of the object so the text is never clipped."
    },
    {
      "type": "CheckBoxObject",
      "description": "A checkbox control for toggling a boolean variable value on or off. Always keep width and height equal (square) when sizing."
    },
    {
      "type": "CircleObject",
      "description": "An ellipse/circle shape. Use for indicators, status lights, or decorative round elements."
    },
    {
      "type": "DataTableObject",
      "description": "Displays tabular data from an external database query with configurable SQL, refresh interval, and styling."
    },
    {
      "type": "DateTimePickerObject",
      "description": "An interactive date/time picker for reading and writing datetime variable values. Supports date-only, time-only, and combined date-time modes."
    },
    {
      "type": "DocumentViewerObject",
      "description": "Shows a document inline on a runtime page, fetched over an authenticated URL so the file never has to be published anonymously. data-documentpath holds the full path of the file, or the name of a variable holding one (typically a client variable, so an operator can choose what the frame shows); when that value changes the frame loads the new document. Access is decided entirely by the DocumentViewerAccess parameter: the file is served only when its folder is listed there or is below a listed folder, the caller must be logged in, and Guests are always refused. An empty matrix serves nothing. Served file types: pdf, png, jpg, jpeg, gif, txt. Sizing: give the frame at least 50% of the screen width (about 960 px on a 1920 px wide screen) so a page-sized document stays readable without horizontal scrolling."
    },
    {
      "type": "DonutObject",
      "description": "A donut/pie chart for displaying proportional data from a JSON variable source."
    },
    {
      "type": "DropDownObject",
      "description": "A dropdown list for selecting a value from a predefined set of items. Items come either from data-items/data-values, or - when data-documentfolder is set - from the documents that actually exist in a folder, which is how an operator picks a previously rendered report without a page having to construct its file name."
    },
    {
      "type": "EventViewerObject",
      "description": "Embeds the full Event Viewer page on a runtime page. Apart from geometry, border, visibility and access control it has no settings of its own, and the framed page keeps enforcing its own user-group rights. Sizing: give the frame at least 80% of the screen width (about 1536 px on a 1920 px wide screen) so the framed page\u0027s toolbar, filters and table columns stay usable."
    },
    {
      "type": "GroupObject",
      "description": "A container that groups child objects into a reusable symbol. Supports symbol libraries, replacers, and synchronized versioning. Group box rule: omit width/height when creating a group and the API derives the box from the children\u0027s extent; a supplied box is kept as-is but children must fit inside it (a child reaching outside the box is rejected, naming the required size), because the API does not re-normalize group geometry the way the designer does. Role matrix for MCP clients: plain group = data-groupsymbol empty and data-groupsymbolmaster empty; reusable master/template = data-groupsymbol set and data-groupsymbolmaster empty; instance = both data-groupsymbol and data-groupsymbolmaster set. Recommended MCP workflow: use CreateDesignObjects or UpdateDesignObjects to create a plain group or to structurally create/edit a master/template with its children; use CreateGroupSymbolInstance to create an instance from an existing master/template; use PushGroupSymbolMaster to propagate master/template changes to selected or all instances. Normal template flow is to edit the master/template structure and then push, rather than manually editing instance children. When the user asks to create a symbol from existing objects already placed on the screen, create or update a GroupObject and copy those existing objects into its children. Adjust each moved child object\u0027s top/left values so they become relative to the GroupObject instead of the page; the GroupObject container itself remains positioned relative to the page. After the children have been moved into the GroupObject, delete the original standalone objects from the page so they are not left behind as duplicates."
    },
    {
      "type": "ImageObject",
      "description": "Displays a static or dynamic image from a base64 data URL."
    },
    {
      "type": "InputObject",
      "description": "A text input field for reading and writing variable values. Supports numeric formatting, password mode, and an optional on-screen numpad."
    },
    {
      "type": "KnobObject",
      "description": "A rotary knob control for reading and writing numeric variable values within a configured min/max range."
    },
    {
      "type": "LabelObject",
      "description": "A text label for displaying static text or live variable values. Supports formatting, alignment, and border styling. Internally this behaves like a textarea, so when setting text and/or font-size, account for the object\u0027s width, height, and padding so the text is never clipped. Bold text and padding can require extra height. For example, a 16px font may need about 30px height to fit cleanly."
    },
    {
      "type": "ListBoxObject",
      "description": "A list box for selecting one or multiple values from a predefined set of items. Items come either from data-items/data-values, or - when data-documentfolder is set - from the documents that actually exist in a folder."
    },
    {
      "type": "MapObject",
      "description": "An interactive geographic map that renders a tiled basemap and positions group symbol children by latitude/longitude. Configure the basemap preset, the initial center and zoom, and whether the runtime user may pan and zoom. The map children themselves are group symbol instances managed from the designer through Edit Map Children and are not part of this object\u0027s attribute contract."
    },
    {
      "type": "PageObject",
      "description": "The page itself rather than an object on it: the container whose background, size, page script, zoom/pan, refresh time and replacers are read with GetDesignPage and written with UpdateDesignPage. It cannot be created or deleted through the object tools; a page is a configuration entity (entity type Pages)."
    },
    {
      "type": "PolygonObject",
      "description": "A filled SVG polygon shape defined by a custom point list. Use for custom shapes, area highlights, or decorative regions on a process overview."
    },
    {
      "type": "PolylineObject",
      "description": "Used for lines, polylines, piping, electrical routes, hydraulic lines, pneumatic lines, conduits, and similar technical linework. PolylineObject is the recommended object for schematic paths and network-style drawings on overview pages, P\u0026ID-style screens, and other technical views. Before creating, routing, or modifying PolylineObject connections, it is strongly recommended to call GetPolylineRoutingGuidelines() and follow that guidance unless the user explicitly requests a different routing style."
    },
    {
      "type": "RecipeManagerObject",
      "description": "Displays the ENVISION recipe manager interface for reading and writing recipe parameter sets."
    },
    {
      "type": "SliderObject",
      "description": "A linear slider control for reading and writing numeric variable values within a configured min/max range."
    },
    {
      "type": "SquareObject",
      "description": "A rectangle shape. Use for panels, separators, or any rectangular visual element inside the page. Do not use SquareObject for the page background; set the background color on the page itself via UpdateDesignPage tool instead."
    },
    {
      "type": "SVGObject",
      "description": "Embeds arbitrary SVG content with dynamic fill and stroke color support. Use for custom icons, symbols, or vector graphics."
    },
    {
      "type": "ToggleObject",
      "description": "A toggle switch control for writing on/off (set/reset) to a variable. Displays state-driven on and off labels. Maintain the aspect ratio when resizing (roughly 1:2.1)."
    },
    {
      "type": "TrendAnalystViewerObject",
      "description": "Embeds the full Trend Analyst page on a runtime page. data-config is its one setting: a Trend Analyst configuration as JSON (see the data-config attribute description for the schema; set HideMenu, HideSummary and HideSliders to true for an embedded chart-only view), or the name of a variable holding one (typically a client variable), which is pushed into the frame and applied live. The framed page keeps enforcing its own user-group rights. Sizing: give the frame at least 80% of the screen width (about 1536 px on a 1920 px wide screen) so the framed page\u0027s toolbar, filters and table columns stay usable."
    },
    {
      "type": "TrendObject",
      "description": "A real-time line chart for displaying and comparing up to four variable trends over a configurable time window. Pens 5 to 8 exist in the designer but are not drawn at runtime, so plan a chart around four pens and use a second TrendObject beyond that."
    },
    {
      "type": "UsersViewerObject",
      "description": "Embeds the full Users page on a runtime page, so user administration can be reached without leaving the graphics. Apart from geometry, border, visibility and access control it has no settings of its own, and the framed page keeps enforcing its own user-group rights. Sizing: give the frame at least 80% of the screen width (about 1536 px on a 1920 px wide screen) so the framed page\u0027s toolbar, filters and table columns stay usable."
    },
    {
      "type": "WebFrameObject",
      "description": "Embeds an external web page or static HTML page in an iframe. Supports optional postMessage communication."
    },
    {
      "type": "WidgetObject",
      "description": "Embeds arbitrary HTML/CSS/JavaScript as a self-contained widget. Use for custom controls or third-party integrations. Only use the widget object when something cannot be build with standard objects."
    }
  ]
}

