{
  "entityType": "ModbusTcpVariables",
  "description": "Variables under a Modbus TCP device.",
  "operations": [
    "get",
    "insert",
    "update",
    "delete"
  ],
  "restPath": "/API/Config/ModbusTcpVariables",
  "parentIdName": "deviceId",
  "parentEntityType": "ModbusTcpDevices",
  "supportsParentFilterOnGet": true,
  "insertSchema": {
    "fields": {
      "deviceName": {
        "valueType": "string",
        "required": false
      },
      "arrayCount": {
        "description": "Plain variable array (no UDT). 0 or 1 = an ordinary single variable; 2 to 512 makes THIS row the array PARENT (element 0) and auto-creates the remaining element rows. The Name must end in a bracket index such as Temps[0], which sets the base name and the start index - there is no separate start field. Elements are named base[start\u002Bk], and editing the parent (resize, rename, retype, re-address) applies to every element immediately. Element rows are locked: they cannot be edited or deleted directly, only through the parent, or released with VariableArrays/Ungroup. Optional; not sent means 0. Address stride: element k advances the register or bit address by k times the type width (INT/UINT/WORD \u002B1 register, DINT/UDINT/DWORD/REAL \u002B2, LINT/ULINT/LREAL \u002B4; coils and discretes \u002B1 bit). Bit-selector and STRING addresses cannot be arrayed.",
        "valueType": "integer",
        "required": false
      },
      "enable": {
        "valueType": "boolean",
        "required": true
      },
      "name": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^(\\{Device\\}\\.)?[a-zA-Z0-9_\\[\\]]\u002B(?:\\.[a-zA-Z0-9_\\[\\]]\u002B)*$"
        }
      },
      "asset": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^$|^[a-zA-Z0-9_](?:[a-zA-Z0-9_ /]*[a-zA-Z0-9_])?$",
          "allowEmpty": true
        }
      },
      "type": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^(BOOL|BYTE|INT|UINT|WORD|REAL|DINT|UDINT|DWORD|LINT|ULINT|LREAL|STRING)$",
          "allowedValues": [
            "BOOL",
            "BYTE",
            "INT",
            "UINT",
            "WORD",
            "REAL",
            "DINT",
            "UDINT",
            "DWORD",
            "LINT",
            "ULINT",
            "LREAL",
            "STRING"
          ]
        }
      },
      "address": {
        "description": "Modbus register address in IEC prefix notation or standard numeric notation. The regex only screens the character set; the four prefixes are %MW\u003Cn\u003E holding register, %IW\u003Cn\u003E input register, %I\u003Cn\u003E discrete input and %M\u003Cn\u003E coil, all zero-based, for example %MW100 or %M7. Numeric form: 400001-465535 or 40001-49999 holding, 300001-365535 or 30001-39999 input, 100001-165535 or 10001-19999 discrete input, 1-9999 coil. Holding and input registers take an optional bit selector, for example %MW100.0, %MW100.X7 or 400101.5.",
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^[a-zA-Z0-9%.]\u002B$"
        }
      },
      "startNewBlock": {
        "valueType": "boolean",
        "required": false
      },
      "description": {
        "valueType": "string",
        "required": true
      },
      "recipeTargets": {
        "valueType": "string",
        "required": false,
        "default": "",
        "validation": {
          "pattern": "^$|[a-zA-Z0-9,{}_ ]\u002B$",
          "allowEmpty": true
        }
      },
      "recipeParameterName": {
        "valueType": "string",
        "required": false,
        "default": "",
        "validation": {
          "pattern": "^$|^[a-zA-Z0-9_.]\u002B$",
          "allowEmpty": true
        }
      },
      "releasedFields": {
        "valueType": "string",
        "required": false,
        "default": ""
      },
      "trendGroups": {
        "description": "Comma-separated trend group names this variable belongs to; a variable may be in several. A trend group is what an operator picks on the Trend Analyst page: its Add New Pens dialog builds a \u0027Trend group\u0027 filter from the distinct names in use, and choosing one narrows the pen list to the variables carrying that name, so a group is simply a set of pens people want to look at together. Good values are the things an operator would name when asking for a chart: an asset or equipment name (Pump1, Boiler2), an area or line (WaterIntake, Line3), or a measurement family (Temperatures, Flows). This is labelling only - it does not log data (that is Historian) and does not change sampling. The tokens {Device} (alias {DeviceName}) and {VariableName} are expanded at runtime, so one templated name can yield a per-device group. Empty is valid and means the variable is only reachable through the \u0027All\u0027 chip and the dialog\u0027s search and sort.",
        "valueType": "string",
        "required": false,
        "default": "",
        "validation": {
          "pattern": "^$|[a-zA-Z0-9,{}_ ]\u002B$",
          "allowEmpty": true
        }
      },
      "userGroups": {
        "description": "Comma-separated user groups allowed to WRITE this variable from the runtime (reading is not restricted here). EMPTY - the default on every new row - means no user group may write it: only members of Administrators can, so name the operator groups explicitly on every point an operator is meant to command. Members of Administrators always may, whatever is listed.",
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^$|[a-zA-Z0-9, ]\u002B$",
          "allowEmpty": true
        }
      },
      "units": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^[^,]\u002B$"
        }
      },
      "minRaw": {
        "valueType": "number",
        "required": true
      },
